// test_kat_sha2_128f is the SLH-DSA-SHA2-128f known-answer test:
// fixed seeds, deterministic signing, exact signature match. The
// vectors were produced by this module and verified with OpenSSL 4.1
// (`openssl pkeyutl -verify -rawin` against a built SPKI key).
fn test_kat_sha2_128f() {
	sk_seed := hex.decode('000102030405060708090a0b0c0d0e0f')!
	sk_prf := hex.decode('404142434445464748494a4b4c4d4e4f')!
	pk_seed := hex.decode('808182838485868788898a8b8c8d8e8f')!
	msg := hex.decode(kat_msg_hex)!
	sk, pk := keygen_internal(.sha2_128f, sk_seed, sk_prf, pk_seed)!
	assert pk.pk_root.hex() == 'f4d82ccf3b7a802113f3a0682465e7e4'
	sig := sign_deterministic(msg, [], sk)!
	assert sig.len == get_params(.sha2_128f).sig_len()
	assert sig.hex() == ''
	assert verify(msg, sig, [], pk)
	// tampered and truncated signatures must not verify
	mut bad := sig.clone()
	bad[sig.len - 1] ^= 0x01
	assert !verify(msg, bad, [], pk)
	assert !verify(msg, sig[..sig.len - 1], [], pk)
	assert !verify('other message'.bytes(), sig, [], pk)
	// context strings change the signature and are enforced
	sig_ctx := sign_deterministic(msg, 'ctx'.bytes(), sk)!
	assert sig_ctx.hex() != sig.hex()
	assert verify(msg, sig_ctx, 'ctx'.bytes(), pk)
	assert !verify(msg, sig_ctx, 'other'.bytes(), pk)
}

