// slow_sha2_kat returns the embedded verify-only vector for a slow
// SHA2 set: public key and deterministic signature over kat_msg_hex.
// The signatures were produced by this module and verified with
// OpenSSL 4.1; signing these sets takes 15-30 s, so only verification
// runs here (same precedent as test_verify_kat_slow_shake_sets).
fn slow_sha2_kat_128s() !(PublicKey, []u8) {
	pk := public_key_from_bytes(.sha2_128s, hex.decode('808182838485868788898a8b8c8d8e8ff9efc654743e550fedc50ae9df21cf39')!)!
	sig := hex.decode('')!
	return pk, sig
}

fn slow_sha2_kat_192s() !(PublicKey, []u8) {
	pk := public_key_from_bytes(.sha2_192s, hex.decode('808182838485868788898a8b8c8d8e8f9091929394959697c089d22eb56e8f3346ff125b1946c1bb1869241d51855365')!)!
	sig := hex.decode('')!
	return pk, sig
}

fn slow_sha2_kat_256s() !(PublicKey, []u8) {
	pk := public_key_from_bytes(.sha2_256s, hex.decode('808182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9f5961566eb17517732f9145c08ebf71207fecddd5f8f8c58f22b104f70ea770e8')!)!
	sig := hex.decode('')!
	return pk, sig
}

// test_verify_kat_slow_sha2_sets checks embedded verify-only vectors
// for the slow SHA2 sets with n = 16, 24 and 32.
fn test_verify_kat_slow_sha2_sets() {
	msg := hex.decode(kat_msg_hex)!
	pk128s, sig128s := slow_sha2_kat_128s()!
	assert sig128s.len == 7856
	assert verify(msg, sig128s, [], pk128s)
	mut bad128s := sig128s.clone()
	bad128s[100] ^= 0x01
	assert !verify(msg, bad128s, [], pk128s)
	pk192s, sig192s := slow_sha2_kat_192s()!
	assert sig192s.len == 16224
	assert verify(msg, sig192s, [], pk192s)
	mut bad192s := sig192s.clone()
	bad192s[100] ^= 0x01
	assert !verify(msg, bad192s, [], pk192s)
	pk256s, sig256s := slow_sha2_kat_256s()!
	assert sig256s.len == 29792
	assert verify(msg, sig256s, [], pk256s)
	mut bad256s := sig256s.clone()
	bad256s[100] ^= 0x01
	assert !verify(msg, bad256s, [], pk256s)
}

// spki_prefix_hex returns the 18-byte SubjectPublicKeyInfo prefix
// (SEQUENCE + SHA2 OID) for a SHA2 set, used to build a PEM public
// key for OpenSSL from raw key bytes. Prefixes were read off
// `openssl pkey -pubout -outform DER` output (OpenSSL 4.1.0).
fn spki_prefix_hex(id ParameterSet) string {
	match id {
		.sha2_128s { return '3030300b0609608648016503040314032100' }
		.sha2_128f { return '3030300b0609608648016503040315032100' }
		.sha2_192s { return '3040300b0609608648016503040316033100' }
		.sha2_192f { return '3040300b0609608648016503040317033100' }
		.sha2_256s { return '3050300b0609608648016503040318034100' }
		.sha2_256f { return '3050300b0609608648016503040319034100' }
		else { return '' }
	}
}

// assert_openssl_verifies checks a V-produced signature with the
// OpenSSL binary (V-to-OpenSSL direction without signing at test
// time) by building a PEM public key from the raw key bytes.
fn assert_openssl_verifies(id ParameterSet, pk_raw []u8, sig []u8, msg []u8, work string) ! {
	mut der := hex.decode(spki_prefix_hex(id))!
	der << pk_raw
	pem := '-----BEGIN PUBLIC KEY-----\n' + base64.encode(der) + '\n-----END PUBLIC KEY-----\n'
	p := get_params(id)
	key_path := os.join_path(work, p.name + '.pem')
	os.write_file(key_path, pem)!
	msg_path := os.join_path(work, p.name + '.msg')
	os.write_bytes(msg_path, msg)!
	sig_path := os.join_path(work, p.name + '.sig')
	os.write_bytes(sig_path, sig)!
	r := os.exec(['openssl', 'pkeyutl', '-verify', '-pubin', '-inkey', key_path, '-in', msg_path,
		'-sigfile', sig_path, '-rawin'])
	assert r.exit_code == 0, r.output
	assert r.output.contains('Verified'), r.output
}

// test_openssl_differential_sha2 cross-checks the SHA2 sets against
// OpenSSL in both directions. Fast sets sign live both ways; for the
// slow sets OpenSSL signs live (V verifies) while the V-to-OpenSSL
// direction replays the embedded KAT signatures through freshly built
// PEM keys, keeping the suite fast. OpenSSL applies the pure-sign
// prefix 0x00 || 0x00 for empty contexts, matching verify().
fn test_openssl_differential_sha2() {
	check := os.exec(['openssl', 'version'])
	if check.exit_code != 0 {
		println('skip openssl sha2 differential test: openssl not available')
		return
	}
	work := os.join_path(os.temp_dir(), 'slh_dsa_diff_sha2')
	os.mkdir_all(work)!
	msg_path := os.join_path(work, 'msg.bin')
	os.write_file(msg_path, 'openssl sha2 differential message')!
	msg := os.read_bytes(msg_path)!
	for id in [ParameterSet.sha2_128f, .sha2_192f, .sha2_256f, .sha2_128s, .sha2_192s, .sha2_256s] {
		p := get_params(id)
		key_path := os.join_path(work, p.name + '.key.pem')
		sig_ossl := os.join_path(work, p.name + '.ossl.sig')
		sig_v := os.join_path(work, p.name + '.v.sig')
		r := os.exec(['openssl', 'genpkey', '-algorithm', p.name, '-out', key_path])
		assert r.exit_code == 0, r.output
		text := os.exec(['openssl', 'pkey', '-in', key_path, '-text', '-noout'])
		assert text.exit_code == 0, text.output
		priv_raw, pub_raw := parse_ossl_key_text(text.output)!
		sk := private_key_from_bytes(id, priv_raw)!
		pk := public_key_from_bytes(id, pub_raw)!
		assert pk.bytes() == sk.public_key().bytes()
		// OpenSSL -> V
		r2 := os.exec(['openssl', 'pkeyutl', '-sign', '-inkey', key_path, '-in', msg_path, '-out',
			sig_ossl, '-rawin'])
		assert r2.exit_code == 0, r2.output
		assert verify(msg, os.read_bytes(sig_ossl)!, [], pk)
		// V -> OpenSSL: live for fast sets, embedded KAT replay for slow sets
		if id == .sha2_128f || id == .sha2_192f || id == .sha2_256f {
			vsig := sign(msg, [], sk)!
			os.write_bytes(sig_v, vsig)!
		} else {
			kat_pk, kat_sig := match id {
				.sha2_128s { slow_sha2_kat_128s()! }
				.sha2_192s { slow_sha2_kat_192s()! }
				else { slow_sha2_kat_256s()! }
			}
			kat_msg := hex.decode(kat_msg_hex)!
			assert_openssl_verifies(id, kat_pk.bytes(), kat_sig, kat_msg, work)
			continue
		}
		r3 := os.exec(['openssl', 'pkeyutl', '-verify', '-pubin', '-inkey', key_path, '-in', msg_path,
			'-sigfile', sig_v, '-rawin'])
		assert r3.exit_code == 0, r3.output
		assert r3.output.contains('Verified'), r3.output
	}
}

// is_hex_colon reports whether s consists of hex digits and colons only.
fn is_hex_colon(s string) bool {
	for c in s {
		if c == `:` {
			continue
		}
		if (c >= `0` && c <= `9`) || (c >= `a` && c <= `f`) || (c >= `A` && c <= `F`) {
			continue
		}
		return false
	}
	return true
}

// parse_ossl_key_text extracts the raw private and public key bytes from
// `openssl pkey -text -noout` output.
fn parse_ossl_key_text(out string) !([]u8, []u8) {
	mut priv_hex := ''
	mut pub_hex := ''
	mut section := 0
	for line in out.split_into_lines() {
		t := line.trim_space()
		if t == 'priv:' {
			section = 1
			continue
		}
		if t == 'pub:' {
			section = 2
			continue
		}
		if t.contains(':') && t.len > 2 && is_hex_colon(t) {
			clean := t.replace(':', '').replace(' ', '')
			if section == 1 {
				priv_hex += clean
			} else if section == 2 {
				pub_hex += clean
			}
		}
	}
	return hex.decode(priv_hex)!, hex.decode(pub_hex)!
}

// test_openssl_differential cross-checks both directions against OpenSSL:
// OpenSSL signs, this module verifies, and vice versa. OpenSSL applies the
// pure-sign prefix 0x00 || 0x00 for empty contexts, matching verify().
fn test_openssl_differential() {
	check := os.exec(['openssl', 'version'])
	if check.exit_code != 0 {
		println('skip openssl differential test: openssl not available')
		return
	}
	work := os.join_path(os.temp_dir(), 'slh_dsa_diff')
	os.mkdir_all(work)!
	msg_path := os.join_path(work, 'msg.bin')
	sig_ossl := os.join_path(work, 'ossl.sig')
	sig_v := os.join_path(work, 'v.sig')
	key_path := os.join_path(work, 'key.pem')
	os.write_file(msg_path, 'openssl differential message')!
	msg := os.read_bytes(msg_path)!
	r := os.exec(['openssl', 'genpkey', '-algorithm', 'SLH-DSA-SHAKE-128f', '-out', key_path])
	assert r.exit_code == 0, r.output
	text := os.exec(['openssl', 'pkey', '-in', key_path, '-text', '-noout'])
	assert text.exit_code == 0, text.output
	priv_raw, pub_raw := parse_ossl_key_text(text.output)!
	sk := private_key_from_bytes(.shake_128f, priv_raw)!
	pk := public_key_from_bytes(.shake_128f, pub_raw)!
	assert pk.bytes() == sk.public_key().bytes()
	// OpenSSL -> V
	r2 := os.exec(['openssl', 'pkeyutl', '-sign', '-inkey', key_path, '-in', msg_path, '-out',
		sig_ossl, '-rawin'])
	assert r2.exit_code == 0, r2.output
	assert verify(msg, os.read_bytes(sig_ossl)!, [], pk)
	// V -> OpenSSL
	vsig := sign(msg, [], sk)!
	os.write_bytes(sig_v, vsig)!
	r3 := os.exec(['openssl', 'pkeyutl', '-verify', '-inkey', key_path, '-in', msg_path, '-sigfile',
		sig_v, '-rawin'])
	assert r3.exit_code == 0, r3.output
	assert r3.output.contains('Verified')
}
